/*
 * A042169  Denominators of continued fraction convergents to sqrt(609).
 * https://oeis.org/A042169
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, frac, easy
 * Formula:   a(n) = denominator of the n‑th convergent to √609
 * Range:     u8 n <= 5, u16 n <= 11, u32 n <= 20, u64 n <= 38, u128 n <= 77,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The continued fraction of √609 is generated by the recurrence:
 *   m₀ = 0,          d₀ = 1,          a₀ = ⌊√609⌋ = 24
 *   mᵢ₊₁ = dᵢ·aᵢ – mᵢ
 *   dᵢ₊₁ = (609 – mᵢ₊₁²) / dᵢ
 *   aᵢ₊₁ = ⌊(24 + mᵢ₊₁) / dᵢ₊₁⌋
 *   p₋₂ = 0,  p₋₁ = 1,  q₋₂ = 1,  q₋₁ = 0
 *   pᵢ   = aᵢ·pᵢ₋₁ + pᵢ₋₂
 *   qᵢ   = aᵢ·qᵢ₋₁ + qᵢ₋₂
 * The function returns qₙ, the denominator of the n‑th convergent.
 * This runs in O(n) time and uses only integer arithmetic. */

seq_t a(idx_t n)
{
    const idx_t A0 = 24;          /* floor(sqrt(609))          */
    const idx_t D  = 609;         /* number under the root      */

    idx_t m = 0, d = 1, a_cf = A0;                 /* continued‑fraction data  */
    seq_t p_prev2 = (seq_t)0, p_prev1 = (seq_t)1;   /* p_{-2}, p_{-1}          */
    seq_t q_prev2 = (seq_t)1, q_prev1 = (seq_t)0;   /* q_{-2}, q_{-1}          */

    for (idx_t k = 0; k <= n; ++k)
    {
        /* compute next convergent */
        seq_t p = (seq_t)a_cf * p_prev1 + p_prev2;
        seq_t q = (seq_t)a_cf * q_prev1 + q_prev2;

        /* shift previous values */
        p_prev2 = p_prev1; p_prev1 = p;
        q_prev2 = q_prev1; q_prev1 = q;

        /* return the denominator once we have reached index n */
        if (k == n)
            return q;

        /* advance to the next term of the continued fraction */
        idx_t m_next = d * a_cf - m;
        idx_t d_next = (D - m_next * m_next) / d;
        idx_t a_next = (A0 + m_next) / d_next;

        m = m_next; d = d_next; a_cf = a_next;
    }
    /* The loop always returns, but return 0 to satisfy the compiler. */
    return (seq_t)0;
}
